struct NlAsset { const char* name; const unsigned char* data; std::size_t size; };
static const NlAsset kAssets[] = {
    { "SSTMedium.TTF", kAsset0, sizeof(kAsset0) },
    { "SSTBold.TTF", kAsset1, sizeof(kAsset1) },
    { "fa-solid-900.ttf", kAsset2, sizeof(kAsset2) },
    { "SpaceGrotesk-SemiBold.ttf", kAsset3, sizeof(kAsset3) },
    { "avatar.rgba", kAsset4, sizeof(kAsset4) },
    { "logo.rgba", kAsset5, sizeof(kAsset5) },
};

void* nl_embedded_asset_reader(const char* name, std::size_t* out_size)
{
    for (const NlAsset& a : kAssets)
    {
        if (std::strcmp(a.name, name) == 0)
        {
            void* copy = IM_ALLOC(a.size);
            std::memcpy(copy, a.data, a.size);
            *out_size = a.size;
            return copy;
        }
    }
    return nullptr;
}
